WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true AND ( EXISTS (SELECT 1 FROM "public"."article" AS "e0" WHERE true AND "e0"."author_id" = "s"."id" AND ( ( true AND ( EXISTS (SELECT 1 FROM "public"."comment" AS "e1" WHERE true AND "e1"."article_id" = "e0"."id" AND ( ( true AND ( "e1"."id" = $1 ) AND ( EXISTS (SELECT 1 FROM "public"."article" AS "e2" WHERE true AND "e2"."id" = "e1"."article_id" AND ( "e2"."author_id" = $2 )) ) ) )) ) AND ( "e0"."author_id" = $3 ) ) )) ) AND ( ( true ) ) ) ) ORDER BY "s"."id" ASC NULLS LAST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0"
